@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           class="product-search__input"
           placeholder="Search products…"
           @oninput="OnSearchInput"
           value="@_query" />

    @if (_loading)
    {
        <div class="product-search__status" role="status">Searching…</div>
    }
    else if (_error is not null)
    {
        <div class="product-search__error" role="alert">
            <p>Search failed: @_error</p>
            <button @onclick="RetrySearch">Retry</button>
        </div>
    }
    else if (_hasSearched && _results.Count == 0)
    {
        <div class="product-search__status">No products found.</div>
    }
    else if (_results.Count > 0)
    {
        <div class="product-search__results" role="list">
            @foreach (var product in _results)
            {
                <div class="product-search__card"
                     role="listitem"
                     @onclick="() => OnProductSelected.InvokeAsync(product)"
                     @key="product.Id">
                    <img class="product-search__card-image"
                         src="@product.ImageUrl"
                         alt="@product.Name"
                         loading="lazy" />
                    <div class="product-search__card-body">
                        <h3 class="product-search__card-name">@product.Name</h3>
                        <p class="product-search__card-price">@product.Price.ToString("C")</p>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private string _query = string.Empty;
    private List<Product> _results = new();
    private bool _loading;
    private bool _hasSearched;
    private string? _error;

    private Timer? _debounceTimer;
    private CancellationTokenSource? _searchCts;

    private void OnSearchInput(ChangeEventArgs e)
    {
        _query = e.Value?.ToString() ?? string.Empty;

        // Cancel any in-flight search immediately so we don't process stale results.
        CancelPendingSearch();

        _debounceTimer?.Dispose();
        _debounceTimer = new Timer(OnDebounceElapsed, null, 300, Timeout.Infinite);
    }

    private async void OnDebounceElapsed(object? state)
    {
        // Timer fires on a thread-pool thread; marshal back to the sync context.
        await InvokeAsync(ExecuteSearch);
    }

    private async Task ExecuteSearch()
    {
        var query = _query.Trim();
        if (string.IsNullOrEmpty(query))
        {
            _results = new();
            _hasSearched = false;
            _error = null;
            _loading = false;
            StateHasChanged();
            return;
        }

        CancelPendingSearch();
        _searchCts = new CancellationTokenSource();
        var ct = _searchCts.Token;

        _loading = true;
        _error = null;
        StateHasChanged();

        try
        {
            var results = await ProductService.SearchAsync(query, ct);

            // If this token was cancelled while awaiting, another search
            // has been kicked off — discard these results silently.
            if (ct.IsCancellationRequested)
                return;

            _results = results;
            _hasSearched = true;
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Expected when a newer keystroke supersedes this search. Do nothing.
            return;
        }
        catch (Exception ex)
        {
            if (ct.IsCancellationRequested)
                return;

            _error = ex.Message;
            _results = new();
        }
        finally
        {
            // Only clear the loading flag if this is still the active search.
            if (!ct.IsCancellationRequested)
            {
                _loading = false;
                StateHasChanged();
            }
        }
    }

    private async Task RetrySearch()
    {
        await ExecuteSearch();
    }

    private void CancelPendingSearch()
    {
        _searchCts?.Cancel();
        _searchCts?.Dispose();
        _searchCts = null;
    }

    public void Dispose()
    {
        _debounceTimer?.Dispose();
        CancelPendingSearch();
    }
}

